    private void save(boolean as,Runnable afterSaved){
        if(projectReadOnly())return;
        if(busy||draft==null)return;
        try {
            boolean global=draft.dirty(),object=objectDirty();
            boolean copy=(as&&!objectMode)||(global&&preset.system)||(!global&&!object&&!objectMode&&preset.system);
            if(copy){nameDialog(afterSaved,object);return;}
            if(!global&&!object&&!pendingGlobalFollowup){if(afterSaved!=null)afterSaved.run();return;}
            persist(null,global,object,afterSaved);
        }catch(Exception e){error(e);}
    }
