    private static final class SaveOutcome {PresetRepository.Preset saved;PresetRepository.Draft baseline;JSONObject parent;Exception error;boolean pendingFollowup;}
    private void persist(String name,boolean writeGlobal,boolean writeObject,Runnable afterSaved){
        if(projectReadOnly())return;
        if(busy||draft==null)return;
        final JSONObject objectValues;final ObjectSettingsStore.Snapshot scoped=objectScope;final String currentKind=kind;final boolean retryFollowup=pendingGlobalFollowup;
        try{objectValues=PresetJson.copy(objects);if(writeObject&&scoped==null)throw new IOException(getString(R.string.phase2_settings_object_unavailable));}
        catch(Exception e){error(e);return;}
        messageStatus(getString(R.string.phase2_settings_checking));
        task(()->{
            JSONObject effective=repo.resolveDraft(draft);
            if(writeObject&&!writeGlobal&&!retryFollowup&&!preset.id.equals(SettingsState.activeId(this,currentKind)))
                throw new IOException(getString(R.string.preferences_unsaved_activate_for_object));
            if(writeGlobal)validateCandidate(effective);
            if(writeObject)validateCandidate(PresetJson.merge(effective,objectValues));
            SaveOutcome outcome=new SaveOutcome();outcome.saved=preset;
            if(writeGlobal){outcome.saved=name==null?repo.save(draft):repo.saveAs(draft,name);outcome.pendingFollowup=true;}
            else outcome.pendingFollowup=retryFollowup;
            try{
                if(outcome.pendingFollowup){
                    SettingsState.select(this,outcome.saved.id);
                    if(currentKind.equals("process")){try{ProcessOverridesStore.Identity id=ProcessOverridesStore.Identity.capture(this);ProcessOverridesStore.save(this,id,"{}");}catch(IOException missing){if(SettingsState.capture(this).overlays.size()==3)throw missing;}}
                    outcome.pendingFollowup=false;
                }
                if(writeObject)ObjectSettingsStore.save(this,scoped.modelFileName,scoped.plateIndex,scoped.nativeObjectCount,objectValues);
            }catch(Exception postCommit){
                if(!writeGlobal&&!retryFollowup)throw postCommit;
                outcome.error=postCommit;
                // A committed Save As has a new identity; reset the draft to its exact on-disk baseline.
                outcome.baseline=repo.beginDraft(outcome.saved.id);
                outcome.parent=outcome.saved.parentId==null||outcome.saved.parentId.isEmpty()?new JSONObject():repo.resolve(outcome.saved.parentId);
            }
            return outcome;
        },outcome->{
            if(outcome.error!=null){preset=outcome.saved;draft=outcome.baseline;inherited=outcome.parent;pendingGlobalFollowup=outcome.pendingFollowup;renderEditor();error(outcome.error);return;}
            pendingGlobalFollowup=false;
            toast(writeGlobal?getString(R.string.phase2_settings_saved,outcome.saved.name):getString(R.string.phase2_settings_object_saved));
            open(currentKind,outcome.saved.id,"",()->{ControlPreferences.scheduleAutoSlice(this);if(afterSaved!=null)afterSaved.run();});
        });
    }
